Ext.define('BNK.view.common.NoticeBoardManagementMViewController', {
    extend: 'BaseViewController',
    alias: 'controller.common.noticeboardmanagementm',

    config: {
        viewId: 'NoticeBoardManagementM'
    },

    onSearchTap: function(button, e, eOpts) {
        var me = this,
            vm = me.getViewModel(),
            refs = me.getReferences(),
            searchValue = refs.searchField.getValue();

        var items = refs.searchForm.getItems().items;
        var msg = ''; //validation message
        var fieldName = '';
        for(var i in items){
            if(!Ext.isEmpty(items[i].validate) && !items[i].validate()){

                fieldName = !Ext.isEmpty(items[i].getPlaceholder()) ? items[i].getPlaceholder() : '';
                if(Ext.isEmpty(fieldName)){
                    continue;
                }
                else{
                    msg += ('<br> - ' +fieldName + ' : ' + items[i].getErrorMessage());
                }
            }
        }

        if(!Ext.isEmpty(msg)){
            msg = '입력값을 확인해주세요.' + Ext.String.htmlDecode(msg);
            Ext.Msg.alert('유효성 검증', msg);

            return;
        }


        var params = {
            title : searchValue,
            criYy : refs.criYy.getValue()
        };

        // 공지사항 조건 검색
        var grid = refs.grid;
        grid.getStore().getProxy().extraParams = params;
        grid.getStore().removeAll();
        grid.getStore().loadPage(1);

    },

    onGridSelect: function(dataview, selected, eOpts) {
        var me = this,
            vm = me.getViewModel(),
            refs = me.getReferences(),
            selectedData = selected[0].data;

        var naviView = me.getView().up('navigationview');
        me.PUSH_VIEW(naviView, {
            menuId  : 'NoticeBoardManagementDetailM',
            title   : '공지사항 상세보기',
            isSubView : true,
            parentView : me.getView(),
            records : selectedData
        });

    },

    initialize: function(component, eOpts) {
        var me = this,
            vm = me.getViewModel(),
            refs = me.getReferences(),
            grid = refs.grid;

        // Hidden Grid Header
        grid.el.select('.x-headercontainer').setStyle('height',	'0px');

        refs.criYy.setValue(new Date().getFullYear());
    }

});